<script setup lang="ts">
import{ref,computed,watch}from'vue';import Icon from'./Icon.vue';import{api}from'./api';import{t,bytes,duration,errorText}from'./i18n';import{safeUrl,type Media,type Task}from'../../../packages/contracts';
const props=defineProps<{visible:boolean;tasks:Task[]}>(),emit=defineEmits<{changed:[]}>();const sources=ref<Media[]>([]),selected=ref(''),url=ref(''),error=ref(''),busy=ref(false);
const options=computed(()=>sources.value.flatMap(m=>m.variants.map(v=>({key:`${m.tabId}:${m.id}:${v.id}`,media:m,variant:v}))));
const jobs=computed(()=>props.tasks.filter(t=>t.live).slice(0,10));
async function refresh(){busy.value=true;error.value='';try{sources.value=await api('liveSources');if(!options.value.some(o=>o.key===selected.value))selected.value=options.value[0]?.key??'';}catch(e){error.value=e instanceof TypeError?'invalid':(e as Error).message;}finally{busy.value=false;}}
watch(()=>props.visible,visible=>{if(visible)void refresh();},{immediate:true});
async function start(){busy.value=true;error.value='';try{const source=options.value.find(o=>o.key===selected.value);if(url.value.trim()){const value=safeUrl(url.value.trim());await api('startLive',{url:value});}else if(source)await api('startLive',{tabId:source.media.tabId,id:source.media.id,variantId:source.variant.id});else throw new Error('missing');emit('changed');}catch(e){error.value=e instanceof TypeError?'invalid':(e as Error).message;}finally{busy.value=false;}}
async function action(type:string,id:string){try{await api(type,{id});emit('changed');}catch(e){error.value=e instanceof TypeError?'invalid':(e as Error).message;}}
</script>
<template><section class="settings-card live-panel"><h2 class="panel-title"><Icon name="record" />{{ t('liveTitle') }}</h2><p>{{ t('liveHint') }}</p><div v-if="error" class="alert" role="alert">{{ errorText(error) }}</div><label>{{ t('liveSources') }}<select v-model="selected" :disabled="busy || !!url.trim()" :aria-label="t('liveSources')"><option value="">{{ t('liveNoSource') }}</option><option v-for="item in options" :key="item.key" :value="item.key">{{ item.media.title }} · {{ item.variant.label || 'HLS' }}</option></select></label><button class="text-button" :disabled="busy" @click="refresh"><Icon name="refresh" />{{ t('liveRefresh') }}</button><label>{{ t('liveUrl') }}<input v-model="url" type="url" dir="ltr" placeholder="https://example.com/stream.m3u8" :aria-label="t('liveUrl')"></label><button class="primary" :disabled="busy || (!url.trim() && !selected)" @click="start"><Icon name="record" />{{ t('liveStart') }}</button><p>{{ t('liveBoundary') }}</p><article v-for="job in jobs" :key="job.id" class="live-job" :data-live-task="job.id"><h3 dir="auto">{{ job.title }}</h3><p>{{ t(job.live && !job.live.active && job.state === 'recording' ? 'liveStopping' : job.state) }} · <bdi>{{ duration(job.live!.duration) }}</bdi> · {{ bytes(job.bytes) }}</p><button v-if="job.live?.active && job.state === 'recording'" class="secondary" @click="action('stopLive',job.id)"><Icon name="stop" />{{ t('stopRecording') }}</button><button v-if="job.live!.segments && ['paused','failed'].includes(job.state)" class="secondary" @click="action('recoverLive',job.id)">{{ t('recoverRecording') }}</button><button v-if="job.saved" class="secondary" @click="action('reveal',job.id)">{{ t('show') }}</button><a class="text-button" href="#library">{{ t('library') }}</a><p v-if="job.live?.warning" class="task-notice">{{ t(job.live.warning === 'liveGap' ? 'liveGap' : 'notice_liveIncomplete') }}</p><p v-if="job.error">{{ errorText(job.error) }}</p></article></section></template>
<style scoped>.live-panel label{display:grid;gap:7px;font-size:12px;font-weight:600;margin-block:18px 8px}.live-panel p{font-size:12px;color:var(--muted);line-height:1.7;margin-block:16px}.live-panel select,.live-panel input{inline-size:100%;max-inline-size:none}.live-panel h3{font-size:13px;overflow-wrap:anywhere}.live-job{border-block-start:1px solid var(--border);padding-block:14px}.live-panel .alert{margin-block:16px}.live-panel{margin-block-end:20px}</style>
